import ast,json,sys
from pathlib import Path
from collections import Counter
sys.path.insert(0,'/opt/nvidia/nsight-compute/2026.2.1/extras/python')
import ncu_report
root=Path('/scratch/gpfs/CSES/dmturner/dawa-benchmarks/profile-ndt-20260926')
for n in (1250,20000):
 report=ncu_report.load_report(str(root/f'kernel-{n}.ncu-rep'))
 action=report.range_by_idx(0).action_by_idx(0)
 metrics={}
 for name in action.metric_names():
  if any(s in name for s in ['registers_per_thread','occupancy_limit','warps_active.avg.pct','warps_eligible.avg.per','issue_active.avg.pct','throughput.avg.pct','gpu__time_duration.sum','dram__bytes','local_op','pcsamp_sample_count','dropped','overflow','sampling_interval']):
   metric=action.metric_by_name(name)
   if metric.has_value(): metrics[name]={'value':metric.value(),'unit':metric.unit()}
 metric=action.metric_by_name('smsp__pcsamp_sample_count')
 ids=metric.correlation_ids();lines=Counter();files=Counter();opcodes=Counter()
 for i in range(metric.num_instances()):
  address=ids.as_uint64(i);count=metric.as_uint64(i);source=action.source_info(address)
  f=source.file_name() if source else 'unknown';line=source.line() if source else 0
  lines[f,line]+=count;files[f]+=count
  text=action.sass_by_pc(address).strip();opcodes[text.split()[0] if text else 'unknown']+=count
 sources={}
 for name in files:
  path=Path(name)
  if path.is_file():sources[name]=path.read_text()
 def location(name,line):
  text=sources.get(name,'');rows=text.splitlines();fun='unknown'
  try:
   matches=[x for x in ast.walk(ast.parse(text)) if isinstance(x,(ast.FunctionDef,ast.AsyncFunctionDef)) and x.lineno<=line<=x.end_lineno]
   if matches:fun=min(matches,key=lambda x:x.end_lineno-x.lineno).name
  except SyntaxError:pass
  return {'function':fun,'source':rows[line-1].strip() if 0<line<=len(rows) else ''}
 byline=[{'file':f,'line':l,'samples':v,**location(f,l)} for (f,l),v in lines.most_common()]
 result={'estimates':n,'metrics':metrics,'sample_count':sum(files.values()),'files':dict(files),'lines':byline,'opcodes':dict(opcodes.most_common()),'sources':sources}
 (root/f'hardware-{n}.json').write_text(json.dumps(result,indent=2)+'\n')
 print(n,json.dumps(metrics),flush=True)
